import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"属性与技能接入","description":"","frontmatter":{},"headers":[],"relativePath":"modules/accessory/integration.md","filePath":"modules/accessory/integration.md","lastUpdated":0}`),a={name:`modules/accessory/integration.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="属性与技能接入" tabindex="-1">属性与技能接入 <a class="header-anchor" href="#属性与技能接入" aria-label="Permalink to “属性与技能接入”">​</a></h1><p>饰品的属性和技能不是 EmakiAccessory 自己算的，而是注册到 EmakiAttribute 与 EmakiSkills 的对外接入点上。这两个模块是软依赖，缺失时对应的那一半自动失效，饰品栏本身照常可用。</p><h2 id="属性接入-emakiattribute" tabindex="-1">属性接入 EmakiAttribute <a class="header-anchor" href="#属性接入-emakiattribute" aria-label="Permalink to “属性接入 EmakiAttribute”">​</a></h2><p>EmakiAccessory 向 EmakiAttribute 注册一个<strong>贡献提供者</strong>，把饰品带来的属性作为独立来源汇入战斗快照。它不注册自定义装备槽位，也不写入玩家身上的原版属性。</p><p>上报的来源 id：</p><table tabindex="0"><thead><tr><th>来源 id</th><th>含义</th></tr></thead><tbody><tr><td><code>emakiaccessory:accessory</code></td><td>单件饰品自身的属性。</td></tr><tr><td><code>emakiaccessory:set</code></td><td>饰品套装的加成。</td></tr></tbody></table><p>属性值通过 EmakiAttribute 的 <code>AttributeCatalog#itemSnapshot</code> 读取——<strong>与装备路径同一个解析器</strong>。因此一件饰品和一顶数据相同的头盔产出完全相同的数值，父属性展开与范围伴生键（range spread companion keys）一并生效。</p><p>范围伴生键与普通键一样参与求和，否则带范围的饰品会只保留下界而丢掉浮动区间。</p><h2 id="技能接入-emakiskills" tabindex="-1">技能接入 EmakiSkills <a class="header-anchor" href="#技能接入-emakiskills" aria-label="Permalink to “技能接入 EmakiSkills”">​</a></h2><p>EmakiAccessory 向 EmakiSkills 注册一个<strong>技能来源</strong>。饰品上的装备技能载荷由 <code>EquipmentSkillPdcCodec</code> 读取，与 Item / Forge / Gem / Strengthen 写入的是同一套 PDC 契约。</p><p>饰品套装 <code>thresholds[].effects[].es_skills</code> 里列出的技能也经由同一条路径生效。</p><h2 id="槽位限制判据" tabindex="-1">槽位限制判据 <a class="header-anchor" href="#槽位限制判据" aria-label="Permalink to “槽位限制判据”">​</a></h2><p>饰品和装备一样支持 <code>active_slot</code> 声明。饰品侧的匹配规则：</p><table tabindex="0"><thead><tr><th>物品的 <code>active_slot</code></th><th>结果</th></tr></thead><tbody><tr><td>未声明或为「全部」</td><td>任意饰品槽都生效。</td></tr><tr><td>部位 id，如 <code>ring</code></td><td>该部位的任意一格生效。</td></tr><tr><td>槽位实例 id，如 <code>ring_1</code></td><td>只有这一格生效。</td></tr><tr><td>其他值</td><td>不生效。</td></tr></tbody></table><p>一件物品声明了多个槽位时，<strong>每一条声明都必须被当前格满足</strong>，否则整件物品的贡献被丢弃。这与装备路径「声明的槽位不匹配就丢掉整件物品贡献」的行为一致。</p><p>饰品侧的槽位判据是<strong>独立实现</strong>的，因为 <code>itemSnapshot</code> 本身不做槽位过滤，而装备路径的判据是 EmakiAttribute 内部实现。饰品侧额外接受「裸部位 id」这种写法。如果装备侧的判据规则将来发生变化，饰品侧这份实现需要同步更新。</p><h2 id="重算时机" tabindex="-1">重算时机 <a class="header-anchor" href="#重算时机" aria-label="Permalink to “重算时机”">​</a></h2><p>贡献快照在饰品内容发生变化时重算：GUI 编辑、数据加载完成、reload。</p><p>重算<strong>不在提供者回调里进行</strong>。EmakiAttribute 的战斗快照收集器会在计算自己的缓存签名时调用贡献提供者，也就是每次读取战斗快照都会调用一次；把 PDC 解析放在那里等于把物品反序列化搬到战斗热路径上。</p><h2 id="线程要求" tabindex="-1">线程要求 <a class="header-anchor" href="#线程要求" aria-label="Permalink to “线程要求”">​</a></h2><p>重算必须在持有这些物品的玩家的 owner 线程执行：属性解析器会把结果写回物品 PDC 作为缓存，off-thread 执行不安全。</p><h2 id="缺失模块时的行为" tabindex="-1">缺失模块时的行为 <a class="header-anchor" href="#缺失模块时的行为" aria-label="Permalink to “缺失模块时的行为”">​</a></h2><table tabindex="0"><thead><tr><th>缺失的模块</th><th>影响</th></tr></thead><tbody><tr><td>EmakiAttribute</td><td>饰品不提供属性，饰品栏与套装件数统计照常工作。</td></tr><tr><td>EmakiSkills</td><td>饰品不提供技能。</td></tr><tr><td>EmakiItem</td><td><code>unique</code> 去重回退为原版材质判定，仍然生效；依赖 <code>pieces[].item</code> 的饰品套装整体不生效。</td></tr><tr><td>PlaceholderAPI</td><td>文本中的 PAPI 占位符不再替换，原样输出。</td></tr></tbody></table><p>EmakiAccessory 本身<strong>没有</strong> PlaceholderAPI 扩展，不对外提供 <code>%emakiaccessory_*%</code> 占位符；它只是可选地消费 PlaceholderAPI。本模块也<strong>没有</strong>向 CoreLib 动作注册表注册任何动作。</p>`,24)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};